package de.visionlab.visionpush

import okhttp3.Protocol
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import java.io.File
import java.util.concurrent.CopyOnWriteArrayList

/**
 * Conformance test: drives [RealtimeChannel] against the SHARED, language-neutral
 * corpus generated by the `visionpush-realtime` reference oracle
 * (`crates/visionpush-realtime/conformance/corpus.json`) — the SAME corpus the
 * Web and React Native SDKs validate against. This is the artifact that stops the
 * hand-written native Kotlin client from drifting away from the canonical WS
 * protocol: a behaviour the oracle says is required but that Kotlin gets wrong
 * fails here.
 *
 * Like the imperative JS consumer, this asserts the WIRE-OBSERVABLE projection of
 * each scenario — the text frames the client puts on the socket (`SendText`) and
 * the pushes it delivers (`DeliverPush`) — not the oracle's internal abstract
 * actions (`StateChanged`/`StartTimer`/…), which an imperative client cannot
 * observe. Scenarios that need internal-timer control (the auth watchdog's
 * `TimerFired`) are skipped; the channel's own reconnect unit tests cover those
 * natively ([RealtimeChannelTest]).
 */
@RunWith(RobolectricTestRunner::class)
class RealtimeConformanceTest {

    // ── Fakes (mirror RealtimeChannelTest's injectable transport) ─────────────

    /** A no-network [WebSocket] that records the frames the channel sends. */
    private class FakeWebSocket : WebSocket {
        val sent = CopyOnWriteArrayList<String>()
        override fun request() = throw UnsupportedOperationException()
        override fun queueSize(): Long = 0
        override fun send(text: String): Boolean { sent.add(text); return true }
        override fun send(bytes: ByteString): Boolean = true
        override fun close(code: Int, reason: String?): Boolean = true
        override fun cancel() {}
    }

    private class FakeFactory : RealtimeChannel.WebSocketFactory {
        val sockets = CopyOnWriteArrayList<FakeWebSocket>()
        val listeners = CopyOnWriteArrayList<WebSocketListener>()
        override fun newWebSocket(url: String, listener: WebSocketListener): WebSocket {
            val ws = FakeWebSocket()
            sockets.add(ws)
            listeners.add(listener)
            return ws
        }
    }

    private fun dummyResponse(): Response = Response.Builder()
        .request(Request.Builder().url("https://example.com").build())
        .protocol(Protocol.HTTP_1_1)
        .code(101)
        .message("Switching Protocols")
        .build()

    // Events an imperative client (real socket + timers) can drive — everything
    // except internal timer fires, which need a fake clock. Matches the JS runner.
    private val drivable = setOf("start", "TransportOpened", "TransportClosed", "Shutdown", "TextReceived")

    @Test
    fun nativeClientConformsToTheSharedCorpus() {
        val corpus = JSONObject(loadCorpus())
        val scenarios = corpus.getJSONArray("scenarios")
        var ran = 0
        for (i in 0 until scenarios.length()) {
            val sc = scenarios.getJSONObject(i)
            val steps = sc.getJSONArray("steps")
            if (!allDrivable(steps)) continue
            runScenario(sc.getString("name"), sc.getJSONObject("config"), steps)
            ran++
        }
        // Guard against a silently-empty run (e.g. a relocated/renamed corpus that
        // parses but yields nothing drivable).
        assertTrue("expected at least one drivable corpus scenario", ran >= 3)
    }

    private fun allDrivable(steps: JSONArray): Boolean {
        for (i in 0 until steps.length()) {
            if (eventKind(steps.getJSONObject(i).getJSONObject("send")) !in drivable) return false
        }
        return true
    }

    private fun runScenario(name: String, cfg: JSONObject, steps: JSONArray) {
        val factory = FakeFactory()
        val deliveries = CopyOnWriteArrayList<String?>()
        val channel = RealtimeChannel(
            baseUrl = "https://api.visionpush.de/v1",
            apiKey = cfg.getString("api_key"),
            installationId = cfg.getString("installation_id"),
            appId = cfg.getString("app_id"),
            onPush = { _, frame -> deliveries.add(frame.notificationId.ifEmpty { null }) },
            factory = factory,
        )

        val wantSends = mutableListOf<String>()
        val wantDeliveries = mutableListOf<String?>()
        for (j in 0 until steps.length()) {
            val step = steps.getJSONObject(j)
            drive(channel, factory, step.getJSONObject("send"))
            val expect = step.getJSONArray("expect")
            wantSends.addAll(sendsOf(expect))
            wantDeliveries.addAll(deliveriesOf(expect))
        }

        // Wire projection: every frame the client put on the socket equals the
        // corpus's expected frames, in order (structural JSON equality — key order
        // is irrelevant). e.g. `push_is_acked` fails for any client that doesn't ack.
        val gotSends = factory.sockets.flatMap { it.sent }
        assertEquals("scenario '$name': sent-frame count", wantSends.size, gotSends.size)
        for (k in gotSends.indices) {
            // Structural equality (key order is irrelevant); Android's stripped
            // `org.json` has no `JSONObject.similar`, so canonicalize and compare.
            assertEquals(
                "scenario '$name': sent frame #$k mismatch",
                canonical(JSONObject(wantSends[k])),
                canonical(JSONObject(gotSends[k])),
            )
        }

        // Deliveries: same count and notification ids (the SDK uses "" for "none").
        assertEquals("scenario '$name': deliveries", wantDeliveries, deliveries.toList())

        channel.disconnect()
    }

    private fun drive(channel: RealtimeChannel, factory: FakeFactory, send: JSONObject) {
        when (eventKind(send)) {
            "start" -> channel.connect()
            "TransportOpened" ->
                factory.listeners.last().onOpen(factory.sockets.last(), dummyResponse())
            "TransportClosed" ->
                factory.listeners.last().onClosed(factory.sockets.last(), 1006, "closed")
            "Shutdown" -> channel.disconnect()
            "TextReceived" ->
                factory.listeners.last()
                    .onMessage(factory.sockets.last(), send.getJSONObject("event").getString("TextReceived"))
        }
    }

    /** `start`, or the event name — a string (`"TransportOpened"`) or the single
     *  key of an object event (`{"TextReceived": …}`). Mirrors the JS `eventKind`. */
    private fun eventKind(send: JSONObject): String {
        if (send.has("start")) return "start"
        val ev = send.get("event")
        return if (ev is String) ev else (ev as JSONObject).keys().next()
    }

    /** The `SendText` frames in an expected-action list, in order. */
    private fun sendsOf(expect: JSONArray): List<String> {
        val out = mutableListOf<String>()
        for (i in 0 until expect.length()) {
            val a = expect.get(i)
            if (a is JSONObject && a.has("SendText")) out.add(a.getString("SendText"))
        }
        return out
    }

    /** The delivered notification ids in an expected-action list (`null` = none). */
    private fun deliveriesOf(expect: JSONArray): List<String?> {
        val out = mutableListOf<String?>()
        for (i in 0 until expect.length()) {
            val a = expect.get(i)
            if (a is JSONObject && a.has("DeliverPush")) {
                val dp = a.getJSONObject("DeliverPush")
                out.add(if (dp.isNull("notification_id")) null else dp.getString("notification_id"))
            }
        }
        return out
    }

    /** A canonical, key-sorted serialization of an org.json value, so two frames
     *  compare equal regardless of object key order. */
    private fun canonical(v: Any?): String = when (v) {
        is JSONObject -> v.keys().asSequence().sorted().joinToString(",", "{", "}") { k ->
            JSONObject.quote(k) + ":" + canonical(v.get(k))
        }
        is JSONArray -> (0 until v.length()).joinToString(",", "[", "]") { canonical(v.get(it)) }
        is String -> JSONObject.quote(v)
        else -> v.toString()
    }

    /** Read the committed corpus by walking up from the test working dir to the
     *  repo root (robust to the Gradle module's working directory). */
    private fun loadCorpus(): String {
        var dir: File? = File(System.getProperty("user.dir") ?: ".").absoluteFile
        while (dir != null) {
            val f = File(dir, "crates/visionpush-realtime/conformance/corpus.json")
            if (f.isFile) return f.readText()
            dir = dir.parentFile
        }
        throw IllegalStateException(
            "conformance corpus.json not found from ${System.getProperty("user.dir")}",
        )
    }
}
